import datetime,hashlib,json,pathlib
root=pathlib.Path.cwd();out=root/'.build/cyd-memory-transfer-audit-01';path=out/'report.json';r=json.loads(path.read_text(encoding='utf-8'))
r['already_present']=[
 {'feature':'Shared adaptive compressed-input queue','evidence':['idf/components/native_stream/adaptive_input.c','idf/esp32c3-oled-native/main/adaptive_input.c','idf/esp32-cyd2usb-native/main/audio_service.c:1318'],'details':'C3 compatibility TU includes the same shared queue used by CYD. IDLE-only reclaim, no WRITING/READY/READING eviction, independently allocated slots, FIFO control storage, deferred busy-slot retirement and set_limit/restore APIs already exist. CYD allocates nominal16KiB target and four full packet floor; no second queue implementation is needed.'},
 {'feature':'Release old decoder/PCM before next handshake','evidence':['idf/esp32-cyd2usb-native/main/audio_service.c:573'],'details':'CYD stream owner waits for decoder_released_generation before opening the next HTTP/TLS client; generation cancellation drops obsolete reads. This memory-peak ordering is already transferred.'},
 {'feature':'Full TLS compatibility sizes and same-owner HTTP lifecycle','evidence':['firmware/development/esp32-cyd2usb-native-network-settings-pdm/sdkconfig.json','idf/esp32-cyd2usb-native/main/audio_service.c:592'],'details':'Current saved CYD uses full16384input/4096output TLS limits, internal heap and one synchronous GET owner; cleanup is complete before maintenance stream ack. Do not reduce record limits to fund any experiment.'}
]
r['missing_or_incompatible']=[
 {'feature':'Post-header HTTP request TX release','facts':'CYD source/public SDK/map has no yoradio_http_client_release_request_buffer and no build-local HTTP patch registration. The SDK allocates client->request->buffer->data with malloc(client->buffer_size_tx) at initialization and ordinarily retains it until cleanup. Current radio config requests4096bytes; allocator overhead/usable allocation size and physical fragmentation savings are not measured here.'},
 {'feature':'TLS allocation-pressure reclaim binding','facts':'esp_mbedtls_mem_calloc/free exist in both pinned SDKs and current CYD map, but neither __wrap symbol is linked on CYD. C3 globals bind its app-lifetime queue; CYD has real startup rollback that frees the queue, so bind only after successful startup publication (or introduce proven detach/inflight protection). No allocation/SDK call may run while holding the queue spinlock.'},
 {'feature':'Dynamic TLS RX-only static reserve','facts':'Pinned CYD SDK source has all four donor RX allocation entry functions and esp_mbedtls_mem/free APIs, but current production dynamic-buffer config isOFF so dynamic RX symbols are not linked. Existing C3 source hash guards reject both CYD HTTP and dynamic TLS source. An RX-only static slot has no audited caller unless a deliberate dynamic-TLS port is enabled, and would otherwise permanently cost RAM without serving RX.'},
 {'feature':'SDK6.0.2/6.1 ownership differences','facts':'HTTP prepare_first_line/prepare/fetch_headers/read/cleanup exact spans match between SDKs; request_send differs by newer strict-header guards. Dynamic static-conversion/reset/free RX spans match, but add_rx differs in TLS1.3 CCS/full-record sizing and pointer-offset helpers changed. Keep SDK6.0.2 unrelated behavior byte-identical in a narrow local patch; do not weaken source guards or transplant the newer full SDK file.'}
]
r['candidates']=[
 {'id':'M13-HTTP-TX','priority':1,'bounded_change':'Add a new exact-SDK6.0.2 build-local generator that only ensures a released request buffer is reallocated at original client->buffer_size_tx before request generation, and appends one same-owner synchronous completed-GET release API. Do not modify installed SDK or import SDK6.1 strict-header/auth/redirect changes. Parent has authorized a prototype/new-tool host proof only; production CMake/header/callsite integration is deferred until agreed.' ,'ownership_contract':'Release only non-null client/request/buffer, synchronous GET, post_len==0,data_write_left==0,state==RES_ON_DATA_START. Idempotent NULL data release. Retain request header dictionary, URL/query/auth data, response RX/raw/cached body and borrowed post_data. Reuse allocates original configured capacity before any sender dereference; allocation failure returns NO_MEM before writing and keeps the released state retryable. Partial/async/header-sent/POST/body states must reject release. Same owner task only; no concurrent client use.','expected_effect':'Current CYD radio requests4096TX bytes: release that requested payload after final accepted headers, without reducing URLs/header capacity or TLS record size. Exact heap usable-size/fragmentation benefit remains to measure; do not claim exact physical4096byte heap gain.','proposed_owned_paths':['tools/patch_cyd_http_request_buffer.py','tests/run-cyd-http-request-buffer.py','tests/native/cyd_http_request_buffer/test.c'],'required_executable_evidence':['Exact raw or LF-normalized SDK6.0.2 guard accepts pinned source; wrong/mutated source and already-patched source reject; unmodified input bytes recover exactly after removing only the two inserted spans.','Actual SDK6.0.2 request preparation/sender plus real http_header/http_utils compile under strict host warnings and ASan/UBSan. No copied mocked sender implementation.','Long URL and paginated headers preserve exact wire bytes across release/reuse; repeated release/cleanup has no double free; reallocation OOM retries without partial wire output.','Async partial write/body/POST/auth-redirect retry preparation states retain their live TX storage; released GET may reuse for subsequent GET/POST at full capacity, preserving untouched dictionaries/body and response bytes.','Named semantic controls detect missing reallocation, premature release/borrowed body corruption and duplicate frees by a semantic oracle rather than accepting a sanitizer crash.','Later production integration: actual stream owner release only after open_stream final accepted headers; current redirect chain, auth, Stop/EOF/maintenance and all SDK build/backend gates remain required.']},
 {'id':'M13-IDLE-RECLAIM','priority':2,'bounded_change':'Extract a small optional shared allocation-pressure wrapper around esp_mbedtls_mem_calloc that reclaims only shared adaptive queue idle slots above its existing minimum, retries a bounded number of allocations and otherwise delegates unchanged. No permanent static TLS slot, dynamic-buffer toggle,32KiB headroom or IRAM change.','ownership_contract':'Bind a queue only after CYD startup has fully succeeded and its lifetime is retained; leave NULL throughout rollback/failure. If future runtime teardown is introduced, provide detach/inflight reference protocol before queue destruction. On SMP, concurrent TLS contexts and consumer returns must never use a freed queue or hold allocator calls under queue lock. Keep calloc zero/overflow semantics, queued bytes and producer/consumer/control leases.','required_executable_evidence':['Actual wrapper+shared queue concurrent host tests cover busy producer/consumer/FIFO/control lease preservation, overflow/zero delegate behavior, repeated allocator failure, bounded reclaim and restore only by stream owner between connections.','Actual CYD startup failure at every gate leaves hook unbound; actual successful publication precedes any hook use; expose narrow snapshot counters without logging/allocating in hooks.','Link/ELF evidence for pinned Xtensa archive references confirms __wrap calloc chain and absence of new unexpected allocator paths.','TLS/WebUI/OTA concurrent contexts and all-codec physical memory peaks/jitter need measurement before default enablement.'],'status':'Separate next candidate; parent explicitly deferred while candidate1 prototype is developed.'},
 {'id':'M13-RX-SLOT','priority':3,'bounded_change':'Only after CYD measurements justify it: independently audit SDK6.0.2 dynamic RX allocation/free/static-conversion chain, exact private layout/capacity and all TLS1.2/1.3 record paths; default-off option may share an aligned static slot with CAS fallback and zeroize-on-release.','blocked_from_blind_transfer':['Current CYD dynamicTLS isOFF; donor generator hash rejects CYD source.','Static permanent reserve competes with decoder/DMA/WebUI and affects HTTP as well as HTTPS memory budgets; queue minimum/funding must be measured on CYD.','A static pointer must be released by exactly the matching wrapped SDK free chain, never ordinary free/heap_caps_free or another context; simultaneous contexts must fall back safely.','No C3 32KiB advisory headroom, WiFi IRAM OFF knobs or private RISC-V ABI values may be copied.'],'status':'Measurement/audit gated; not the first implementation.'}
]
r['measurements_before_numeric_policy']=[
 'On CYD per vendor/custom codec and each audio backend, record internal8bit free/largest block and minimum across initial boot, before/after TLS handshake, first full decode, steady playback, Stop, station switch, maintenance and OTA.',
 'Record actual requested versus allocator usable TX bytes at init/release/reuse and largest-block change; requested4096 does not equal guaranteed physical recovery4096.',
 'Record queue resident/minimum/target/occupied/ready bytes and producer/decoder leased slots; nominal16KiB rounds to complete packet allocations and metadata overhead.',
 'Measure HTTP/HTTPS continuity/jitter, full16KiB TLS records and certificate chains alongside WebUI clients/OTA; reclaim can preserve bytes yet reduce delivery reserve.',
 'Measure both-core task stack high-water marks and SDK/DMA/WiFi/WebUI retained heap. Static/map sizes or emulator HWM do not establish physical margins.',
 'Retain CYD existing WiFi IRAM options, two-core affinities, DAC/I2S/PSRAM configuration and record-size limits until separately measured evidence supports a change.'
]
r['ownership_risks']=[
 'CYD rollback destroys s_encoded and resets startup state; copying C3 global reserve bind before all allocations/tasks/output initialization would permit a stale pointer in later TLS allocations. Binding after the final nonfallible startup point avoids this current teardown path.',
 'mbedTLS global allocator wrapper can run for any client/server TLS context on either core, not only the radio stream. Scope and fallback/queue lifetime must account for that.',
 'HTTP client handles are owned by one stream task. Freeing private request data through a guessed public opaque struct layout is unacceptable; use a hash-audited build-local SDK source extension.',
 'C3 generic large reserve selects allocation by size, RX-only reserve selects audited RX sites. These policies are semantically different and neither follows from merely finding similarly named SDK symbols.'
]
r['findings']=[]
r['limitations']=['No host/SDK/target builds or tests ran during this audit; patch acceptance was evaluated as a pure bytes-to-bytes function without writing installed SDK. Proposed executable tests are not claimed passed.','Existing map address rows establish linked symbol presence/absence for those completed build files only; not ABI-layout or dynamic behavior proof.','SDK function extraction used conditional-source-aware manual inspection when a naive brace helper could not parse preprocessor alternatives; whole frozen source/diffs are retained.','No physical CYD heap/jitter/stack data collected; stage13 tuning and acceptance remain open. Deferred AAC owner-view was not investigated.']
r['sources_unchanged_after']={name:hashlib.sha256((root/name).read_bytes()).hexdigest()==digest for name,digest in r['source_sha256'].items()}
r['sdk_unchanged_after']={name:hashlib.sha256(pathlib.Path(name).read_bytes()).hexdigest()==digest for name,digest in r['sdk_sha256'].items()}
assert all(r['sources_unchanged_after'].values()) and all(r['sdk_unchanged_after'].values())
r['reviewed_utc_final']=datetime.datetime.now(datetime.timezone.utc).isoformat();r['result']='Concrete first bounded candidate: audited SDK6.0.2 completed-GET TX-buffer release; queue-pressure wrapper is separate, and static RX reserve/config tuning remains measurement-gated.'
path.write_text(json.dumps(r,indent=2)+'\n',encoding='utf-8');print('Audit finalized',hashlib.sha256(path.read_bytes()).hexdigest())
